using namespace llvm;

namespace llvm {
class PassBuilder;
}

extern "C" int
optMain(int argc, char **argv,
        ArrayRef<std::function<void(PassBuilder &)>> PassBuilderCallbacks);

int main(int argc, char **argv) { return optMain(argc, argv, {}); }

